        EventList eventList = new EventList(userSession.getId());

        MessageContainer<EventList> getEventList = new MessageContainer<>("GET_CART_EVENT_LIST", eventList);
        MessageContainer<?> response = clientConnection.sendDataToServer(getEventList);

        if (response.getType().equals("GET_CART_EVENT_LIST_SUCCESS")) {
            List<EventList> events = (List<EventList>) response.getData();
            return events;
        } else {
            System.out.println("Error in fetching event list");
            return List.of();
        }

    }

    private HBox createListItem(EventList eventList) {
        HBox listItem = new HBox();
        listItem.getStyleClass().add("listItem");

        VBox eventInfoBox = new VBox();
        eventInfoBox.getStyleClass().add("eventInfoBox");

        Label nameLabel = new Label(eventList.getName());
        nameLabel.getStyleClass().add("event-name");

        DateTimeFormatter displayFormatter = DateTimeFormatter.ofPattern("dd-MM-yyyy");
        Label dateLabel = new Label("Date: " + eventList.getDate().format(displayFormatter));

        Label categoryLabel = new Label("Category: " + eventList.getType());
        categoryLabel.getStyleClass().add("category-label");

        HBox dateCategoryBox = new HBox();
        dateCategoryBox.getChildren().addAll(createHBox(dateLabel), categoryLabel);

        VBox placePlaceBox = new VBox();
        Label placeLabel = new Label("Place: " + eventList.getStreet() + ", " + eventList.getCity());
        placePlaceBox.getChildren().addAll(placeLabel);

        VBox placeTicketBox = new VBox();
        Label ticketCountLabel = new Label("Tickets: " + eventList.getTicketsCount());
        ticketCountLabel.getStyleClass().add("ticket-count-label");

        int ticketsCount = eventList.getTicketsCount();
        placeTicketBox.getChildren().addAll(ticketCountLabel);

        Label priceLabel = new Label("Price: " + eventList.getPrice());
        priceLabel.getStyleClass().add("price-label");

        Button deleteButton = new Button("Delete");
        deleteButton.getStyleClass().add("delete-button");
        deleteButton.setOnAction(event -> handleDeleteEvent(event));

        eventInfoBox.getChildren().addAll(nameLabel, dateCategoryBox, placePlaceBox, placeTicketBox, priceLabel, ticketCountLabel);

        Region spacer = new Region();
        HBox.setHgrow(spacer, Priority.ALWAYS);

        listItem.getChildren().addAll(eventInfoBox, spacer, deleteButton);
        listItem.setAlignment(Pos.CENTER_LEFT);

        totalPrice += eventList.getPrice() *eventList.getTicketsCount();
        updateTotalPriceLabel();

        return listItem;
    }

    private void handleDeleteEvent(ActionEvent event) {
        Node source = (Node) event.getSource();
        HBox listItem = (HBox) source.getParent();

        CartAndFavAdd deletedEvent = getSelectedEventFromListItem(listItem);
        sendDeleteRequest(deletedEvent);

        vBoxInScrollPane.getChildren().remove(listItem);

        calculateTotalPrice();
    }

    private void calculateTotalPrice() {
        totalPrice = 0.0;

        for (Node node : vBoxInScrollPane.getChildren()) {
            if (node instanceof HBox) {
                CartAndFavAdd cartItem = getSelectedEventFromListItem((HBox) node);
                totalPrice += cartItem.getPrice() * cartItem.getTicketCount();
            }
        }

        System.out.println("After calculation - Total Price: " + totalPrice);

        updateTotalPriceLabel();
    }

    private CartAndFavAdd getSelectedEventFromListItem(HBox listItem) {
        VBox eventInfoBox = findChildByType(listItem, VBox.class);

        Label nameLabel = findChildByType(eventInfoBox, Label.class);
        HBox dateCategoryBox = findChildByType(eventInfoBox, HBox.class);
        Label dateLabel = findChildByType(dateCategoryBox, Label.class);

        VBox placeSeatsBox = findChildByType(eventInfoBox, VBox.class);
        Label placeLabel = findChildByType(placeSeatsBox, Label.class);
        Label ticketCountLabel = findChildByType(placeSeatsBox, Label.class);
        Label priceLabel = findChildByType(eventInfoBox, Label.class);

        String eventName = nameLabel.getText();
        String eventDateText = dateLabel.getText().replace("Date: ", "");
        DateTimeFormatter displayFormatter = DateTimeFormatter.ofPattern("dd-MM-yyyy");
        LocalDate eventDate = LocalDate.parse(eventDateText, displayFormatter);
        String formattedEventDate = eventDate.format(displayFormatter);

        String placeLabelText = placeLabel.getText().replace("Place: ", "");
        String[] placeComponents = placeLabelText.split(", ");
        String eventStreet = placeComponents[0];
        String eventCity = placeComponents[1];

        int ticketsCount = extractNumericValue(ticketCountLabel.getText());
        float price = extractPriceValue(priceLabel.getText());

        return new CartAndFavAdd(userSession.getId(), eventName, formattedEventDate, eventStreet, eventCity, ticketsCount, price);
    }

    private void sendDeleteRequest(CartAndFavAdd deletedEvent) {
        MessageContainer<CartAndFavAdd> deleteRequest = new MessageContainer<>("DELETE_FROM_CART", deletedEvent);
        clientConnection.sendDataToServer(deleteRequest);
    }

    private void updateTotalPriceLabel() {
        if (totalPrice > 0) {
            totalTicketPrice.setText("TOTAL: $" + String.format("%.2f", totalPrice));
        } else {
            totalTicketPrice.setText("TOTAL: $0.00");
        }
    }

    private <T> T findChildByType(Parent parent, Class<T> type) {
        if (parent == null) {
            return null;
        }

        for (Node child : parent.getChildrenUnmodifiable()) {
            if (type.isInstance(child)) {
                return type.cast(child);
            }
            if (child instanceof Parent) {
                T result = findChildByType((Parent) child, type);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    private int extractNumericValue(String text) {
        if (text.isEmpty()) {
            return 0; // Return 0 for an empty string or handle it based on your requirements
        }

        String numericPart = text.replaceAll("\\D+", ""); // Remove non-numeric characters
        return numericPart.isEmpty() ? 0 : Integer.parseInt(numericPart);
    }

    private float extractPriceValue(String text) {
        if (text.isEmpty()) {
            return 0.f; // Return 0.0 for an empty string or handle it based on your requirements
        }

        String pricePart = text.replaceAll("[^\\d.]+", ""); // Remove non-numeric and non-decimal characters
        return pricePart.isEmpty() ? 0.f : Float.parseFloat(pricePart);
    }


