    player.on('play', function() {
      videos[i].classList.add('is-playing');
      button.classList.remove('hidden');
    });

    player.on('pause', function() {
      videos[i].classList.remove('is-playing');
    });

    // Add click event listener to the control button
    button.addEventListener('click', function() {
      // Use the getPaused method to check if the video is paused
      videos[i].classList.add('!opacity-100');
      player.getPaused().then(function(paused) {
        if (paused) {
          player.play(); // If the video is paused, play the video
          buttonPause.classList.remove('hidden');
          buttonPlay.classList.add('hidden');
        } else {
          player.pause(); // If the video is playing, pause the video
          buttonPause.classList.add('hidden');
          buttonPlay.classList.remove('hidden');
        }
      }).catch(function(error) {
        console.error('Error playing/pausing the video:', error);
      });
