        if(index >= 99){
            mwSampleSum = mwSampleSum + mwSamples[99] - mwSamples[0];
            index = -1;
        }
        index = index +1;
        mwSampleMean = mwSampleSum/100;
        ThisThread::sleep_for(SAMPLING_RATE);
