        if(mwSampleMeanInt < 30){
            ledAState = true;
        }  else{
            ledAState = false; 
        }
        ledA.write(ledAState);
        printf("MW Sensor mean reading  %d Detected %d\n", mwSampleMeanInt, ledAState );
        ThisThread::sleep_for(OUTPUT_UPDATE);
    }
}

