+(NSCharacterSet *) buildTokens {
    static NSCharacterSet *tokens;
    if (tokens == nil) {
        tokens = [NSCharacterSet characterSetWithCharactersInString:@"`=*_~$:!^[]()"];
    }
    return tokens;
}

- (void)onWiki:(MKNode *)lineNode posArrayWiki:(NSArray<NSNumber *> *)posArrayWiki remainingRange:(NSRange)remainingRange offset:(int) offset {
    NSUInteger end = [posArrayWiki objectAtIndex:1].integerValue;
    NSRange range = NSMakeRange(1 + remainingRange.location, end - 1);
    NSString *articleTitle = [self.content ranged:range];

    WikiNode *wiki = [[WikiNode alloc] initWithType:@"wiki" offset:offset  length:articleTitle.length + 4];
    if (![lineNode addChild:wiki]) {
        return;
    }
    MKNode *wikiInner = [[MKNode alloc] initWithType:@"text" offset:  offset + 2 length:articleTitle.length];
    [wiki.children addObject:wikiInner];
    if (![articleTitle containsString:@"|"]) {
        wiki.title = articleTitle;
        NSUInteger pos = [articleTitle indexOf:@"#"];
        if (pos != NSNotFound) {
            NSString *anchor = [[articleTitle substringFromIndex:pos + 1] generateAnchorForHeader];
            if (pos == 0) {
                wiki.destination = [NSString stringWithFormat:@"#%@", anchor];

            } else {
                NSString *pageTitle = [articleTitle substringToIndex:pos];
                wiki.destination = [NSString stringWithFormat:@"marknote://%@#%@",[pageTitle title2url], anchor];
            }
        } else {
            wiki.destination = [NSString stringWithFormat:@"marknote://%@",[articleTitle title2url] ];

        }
    } else {
        NSArray *array = [articleTitle componentsSeparatedByString: @"|"];
        articleTitle = [array objectAtIndex:0];
        NSString *info = [array objectAtIndex:1];
        NSUInteger pos = [articleTitle indexOf:@"#"];
        if (pos != NSNotFound) {
            NSString *anchor = [[articleTitle substringFromIndex:pos + 1] generateAnchorForHeader];
            articleTitle = [articleTitle substringToIndex:pos];
            wiki.destination = [NSString stringWithFormat:@"marknote://%@#%@",[articleTitle title2url], anchor];
        } else {
            wiki.destination = [NSString stringWithFormat:@"marknote://%@",[articleTitle title2url]];

        }
        wiki.title = info;
    }

}

- (void)onLink:(int)i line:(MKNode *)lineNode posArray:(NSArray<NSNumber *> *)posArray {
    LinkTag* link = [[LinkTag alloc] init];
    link.nodeType = @"link";
    link.offset = i;
    link.length = posArray[2].intValue + 2;
    ;
    link.text = [self.content ranged:NSMakeRange(i + 1 , posArray[0].intValue )];
    NSString* surl = [self.content ranged: NSMakeRange( i +  posArray[1].intValue + 2, posArray[2].intValue - posArray[1].intValue - 1)];
    URLTag* urlTag = [[URLTag alloc] initWithString:surl];

    link.url =  urlTag;
    [lineNode addChild:link];
}

- (void)onImage:(int)i line:(MKNode *)line  posArray:(NSArray<NSNumber *> *)posArray withRange: (NSRange) range {
    ImageTag* img = [[ImageTag alloc] init];
    img.offset =  i - 1;
    img.nodeType = @"image";
    img.length = posArray[2].intValue + 3;
    img.alt = [self.content ranged:NSMakeRange(i+1,  posArray[0].intValue )];

    NSString *urlContent = [self.content ranged:NSMakeRange(i + posArray[1].intValue + 2,    posArray[2].intValue  - posArray[1].intValue - 1)];
    URLTag *urlTag = [[URLTag alloc] initWithString:urlContent];
    img.url = urlTag;
    [line addChild: img];

}

-(void)scanToc:(MKNode *)node withRange:(NSRange) range {

    NSArray<NSValue *> *values = [self.content findAllRanges:@"[toc]" withCompareOption: NSCaseInsensitiveSearch range:range];
    for (NSValue *value in values) {
        NSRange range = value.rangeValue;
        ToCNode *toc = [[ToCNode alloc] initWithOffset: range.location length:5];
        [node addChild:toc];
    }
}


- (void)tokenize:(MKNode * _Nonnull)node nodeRange:(NSRange)nodeRange {
    parentNode = node;
    range = nodeRange;
    tokens = [NSMutableArray arrayWithCapacity: (range.length / 2)];
    NSCharacterSet *actionCharset = [LineParser buildTokens];
    for (NSUInteger i = range.location; i <= range.location + range.length - 1; i++) {
        unichar current = [self.content characterAtIndex:i];
        if ([actionCharset characterIsMember:current]) {
            TokenLocation *found = [[TokenLocation alloc] initWithToken:current location:i];
            [tokens addObject:found];
        }
    }
}
- (void)scanBlocks:(MKNode *)line withRange:(NSRange)range {

    [self scanBeginTag:"==" endTag:"==" canEndWithNewLine:NO exclusive:NO withHandler:^(NSUInteger start, NSUInteger end) {
        [self handlBlock:@"mark" start:start end:end tagBeginLength:2 tagEndLength:2];
    }];
    [self scanBeginTag:"$" endTag:"$" canEndWithNewLine:NO exclusive:YES withHandler:^(NSUInteger start, NSUInteger end) {
        [self handlBlock:@"math_inline" start:start end:end tagBeginLength:1 tagEndLength:1];
    }];
    [self scanBeginTag:"***" endTag:"***" canEndWithNewLine:NO exclusive:NO withHandler:^(NSUInteger start, NSUInteger end) {
        [self handlBlock:@"em_strong_emphasis" start:start end:end tagBeginLength:3 tagEndLength:3];
    }];
    [self scanBeginTag:"**" endTag:"**" canEndWithNewLine:NO exclusive:NO withHandler:^(NSUInteger start, NSUInteger end) {
        [self handlBlock:@"strong_emphasis" start:start end:end tagBeginLength:2 tagEndLength:2];
    }];
    [self scanBeginTag:"__" endTag:"__" canEndWithNewLine:NO exclusive:NO withHandler:^(NSUInteger start, NSUInteger end) {
        [self handlBlock:@"strong_emphasis" start:start end:end tagBeginLength:2 tagEndLength:2];
    }];
    [self scanBeginTag:"~~" endTag:"~~" canEndWithNewLine:NO exclusive:NO withHandler:^(NSUInteger start, NSUInteger end) {
        [self handlBlock:@"del" start:start end:end tagBeginLength:2 tagEndLength:2];
    }];
    [self scanBeginTag:"*" endTag:"*" canEndWithNewLine:NO exclusive:NO withHandler:^(NSUInteger start, NSUInteger end) {
        [self handlBlock:@"emphasis" start:start end:end tagBeginLength:1 tagEndLength:1];
    }];
    [self scanBeginTag:"_" endTag:"_" canEndWithNewLine:NO exclusive:NO withHandler:^(NSUInteger start, NSUInteger end) {
        [self handlBlock:@"emphasis" start:start end:end tagBeginLength:1 tagEndLength:1];
    }];
    [self scanBeginTag:"~" endTag:"~" canEndWithNewLine:NO exclusive:NO withHandler:^(NSUInteger start, NSUInteger end) {
        [self handlBlock:@"emphasis" start:start end:end tagBeginLength:1 tagEndLength:1];
    }];
    [self scanBeginTag:"::" endTag:"::" canEndWithNewLine:NO exclusive:NO withHandler:^(NSUInteger start, NSUInteger end) {
        unichar signal = [self.content characterAtIndex:start + 2];
        NSString *nodeType = @"mark_pen_red";
        if (signal == 'y' || signal == 'Y') {
            nodeType = @"mark_pen_yellow";
        } else if (signal == 'g' || signal == 'G') {
            nodeType = @"mark_pen_green";
        }

        [self handlBlock:nodeType start:start end:end tagBeginLength:3 tagEndLength:2];
    }];
}

